// ===== FORM SUBMISSION VIA AJAX =====
function handleFormSubmit(formId, successMsg) {
  const form = document.getElementById(formId);
  if (!form) return;

  form.addEventListener('submit', function(e) {
    e.preventDefault();
    const formData = new FormData(this);
    const submitBtn = this.querySelector('button[type="submit"]');
    const originalText = submitBtn.textContent;

    submitBtn.textContent = 'Sending...';
    submitBtn.disabled = true;

    fetch('/send_mail', {
      method: 'POST',
      body: formData
    })
    .then(response => response.json())
    .then(data => {
      if (data.success) {
        if (formId === 'quoteForm') {
          document.querySelector('#quoteForm').style.display = 'none';
          document.querySelector('.modal-success').style.display = 'block';
        } else {
          form.reset();
          showToast(successMsg || 'Message sent successfully!', 'success');
        }
      } else {
        showToast(data.message || 'Something went wrong. Please try again.', 'error');
      }
    })
    .catch(() => {
      showToast('Network error. Please try again.', 'error');
    })
    .finally(() => {
      submitBtn.textContent = originalText;
      submitBtn.disabled = false;
    });
  });
}

